type UserPreferences = Record<string, string | number | boolean>

// User preferences change on each request, so this fetch opts out of caching.
async function getUserPreferences(): Promise<UserPreferences> {
  try {
    const res = await fetch('https://api.example.com/user/preferences', {
      cache: 'no-store',
    })
    return res.json()
  } catch {
    // Return mock data for build time
    return { theme: 'light', language: 'en', notifications: true }
  }
}

export default async function UserDashboard() {
  const preferences = await getUserPreferences()

  return (
    <div>
      <h2>User Dashboard</h2>
      <dl>
        {Object.entries(preferences).map(([key, value]) => (
          <div key={key}>
            <dt>{key}</dt>
            <dd>{String(value)}</dd>
          </div>
        ))}
      </dl>
    </div>
  )
}

